/**
 * Pollicino-owned host gate injected into pinned LoRaMesher native tests.
 *
 * PNF1 bytes are generated by the current Python FragmentFrame encoder and
 * treated here as an opaque application payload. LoRaMesher must deliver them
 * byte-identically across a two-hop connected segment.
 */

#include <gtest/gtest.h>

#include <algorithm>
#include <ranges>
#include <vector>

#include "pollicino_pnf1_fixture.hpp"
#include "routing_test_fixture.hpp"

namespace loramesher {
namespace test {

class PollicinoPnf1BridgeTests : public RoutingTestFixture {};

TEST_F(PollicinoPnf1BridgeTests, ExactPnf1PayloadAcrossTwoHopChain) {
    ASSERT_GT(kPollicinoPnf1PayloadSize, 18u);
    ASSERT_EQ(kPollicinoPnf1Payload.size(), kPollicinoPnf1PayloadSize);
    ASSERT_EQ(kPollicinoPnf1Payload[0], static_cast<uint8_t>('P'));
    ASSERT_EQ(kPollicinoPnf1Payload[1], static_cast<uint8_t>('N'));
    ASSERT_EQ(kPollicinoPnf1Payload[2], static_cast<uint8_t>('F'));
    ASSERT_EQ(kPollicinoPnf1Payload[3], static_cast<uint8_t>('1'));

    auto nodes = GenerateLineTopology(3, 0x5100, "Pollicino", 0);
    ASSERT_EQ(nodes.size(), 3u);

    for (auto* node : nodes) {
        ASSERT_TRUE(StartNode(*node)) << "Failed to start " << node->name;
    }

    ASSERT_TRUE(WaitForNetworkFormation(nodes, 2))
        << "Network formation failed";
    ASSERT_TRUE(WaitForRoutingStabilization(nodes))
        << "Routing stabilization failed";

    ASSERT_TRUE(HasRouteTo(*nodes[0], nodes[2]->address));
    ASSERT_EQ(GetHopCount(*nodes[0], nodes[2]->address), 2);
    ASSERT_EQ(GetNextHop(*nodes[0], nodes[2]->address), nodes[1]->address);

    ASSERT_TRUE(SendMessage(*nodes[0], *nodes[2], kPollicinoPnf1Payload))
        << "LoRaMesher refused Pollicino PNF1 payload";

    auto superframe_duration = GetSuperframeDuration(*nodes[0]);
    constexpr uint32_t step_ms = 15u;
    bool received =
        AdvanceTime(5000, superframe_duration * 3, step_ms, 0, [&]() {
            return HasReceivedMessageFrom(*nodes[2], nodes[0]->address,
                                          MessageType::DATA);
        });

    ASSERT_TRUE(received)
        << "PNF1 payload did not reach the two-hop destination";

    auto messages = GetReceivedMessages(*nodes[2], nodes[0]->address,
                                        MessageType::DATA);
    ASSERT_EQ(messages.size(), 1u);
    auto received_payload = messages[0].GetPayload();
    ASSERT_EQ(received_payload.size(), kPollicinoPnf1Payload.size());
    EXPECT_TRUE(std::ranges::equal(received_payload, kPollicinoPnf1Payload))
        << "LoRaMesher changed Pollicino PNF1 bytes";
}

}  // namespace test
}  // namespace loramesher
